import{_ as a,o as l,c as e,a2 as i}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"MCP 工具管理","description":"","frontmatter":{"title":"MCP 工具管理"},"headers":[],"relativePath":"zh/guide/mcp-tools.md","filePath":"zh/guide/mcp-tools.md"}'),o={name:"zh/guide/mcp-tools.md"};function r(n,t,s,c,h,d){return l(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="mcp-工具管理" tabindex="-1">MCP 工具管理 <a class="header-anchor" href="#mcp-工具管理" aria-label="Permalink to &quot;MCP 工具管理&quot;">​</a></h1><p>MCP 工具管理用于添加外部工具服务、检查连接、选择可用工具，并把已启用工具分配给 Agent。</p><h2 id="添加工具" tabindex="-1">添加工具 <a class="header-anchor" href="#添加工具" aria-label="Permalink to &quot;添加工具&quot;">​</a></h2><ol><li>从工作台工具管理进入 MCP 区域，选择<strong>添加工具</strong>。</li><li>填写名称与用途，按实际服务选择 <strong>STDIO</strong>、<strong>Streamable HTTP</strong> 或 <strong>SSE</strong>。</li><li>按协议填写所需参数；不要把另一个协议的地址、启动方式或凭证直接复制过来。</li><li>保存后使用界面的连接测试，确认服务可连接。</li><li>查看工具列表，只启用任务需要的工具。</li><li>在 Agent 配置的 MCP 区域选择这些工具并保存。</li></ol><p>服务由你或第三方运行。MCP 服务可用不代表每个工具都安全、成功或适合公开数据。</p><h2 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h2><ul><li>对外部 URL 使用 HTTPS，并按部署网络策略限制可访问地址；不要让工具服务成为访问内部管理接口的通道。</li><li>STDIO 启动的程序继承本机执行能力。仅运行经过审查的程序，限制目录、参数和凭证，不执行来自陌生配置的命令。</li><li>Secret 写入受控凭证或本地配置，不写入公开技能、截图、会话或 Git 仓库。</li><li>工具返回内容属于外部输入，不应被当作更高优先级的系统指令。</li></ul><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><ul><li><strong>连接失败：</strong> 检查服务状态、协议、网络、鉴权和连接测试错误。</li><li><strong>Agent 看不到工具：</strong> 检查工具启用状态和 Agent 的 MCP 选择。</li><li><strong>调用失败：</strong> 查看工具卡片和会话链路中的具体错误，检查参数与外部服务权限。</li><li><strong>返回不可信内容：</strong> 不继续执行其指令，先检查服务来源和工具权限。</li></ul><p><a href="./../mcp.html">MCP 节点参考</a>描述的是工作流触发／集成方式，不要与这里的 Agent 工具管理混为一谈。</p>',10)])])}const m=a(o,[["render",r]]);export{p as __pageData,m as default};
